404:   Subprocess::Options processOptions({"backup", path, grainDir});
405:   processOptions.executable = "/proc/self/exe";
406:   auto inPipe = Pipe::make();
407:   processOptions.stdin = inPipe.readEnd;
408:   Subprocess process(kj::mv(processOptions));
409:   inPipe.readEnd = nullptr;
410: 
411:   auto metadata = params.getInfo();
412:   auto metadataMsg = kj::heap<capnp::MallocMessageBuilder>(metadata.totalSize().wordCount + 4);
413:   metadataMsg->setRoot(metadata);
414:   context.releaseParams();
415:   auto metadataStreamFd = kj::mv(inPipe.writeEnd);
416:   auto output = ioProvider.wrapOutputFd(
417:       metadataStreamFd, kj::LowLevelAsyncIoProvider::ALREADY_CLOEXEC);
418:   auto promise = capnp::writeMessage(*output, *metadataMsg);
419: 
420:   return promise.attach(kj::mv(metadataMsg), kj::mv(metadataStreamFd), kj::mv(output))
421:       .then([KJ_MVCAP(process)]() mutable {
422:     // TODO(cleanup): We should probably use a SubprocessSet to wait asynchronously, but that
423:     //   means we need to use SubprocessSet everywhere...
424:     process.waitForSuccess();
425:   });
