570: kj::Promise<void> BackendImpl::deleteBackup(DeleteBackupContext context) {
571:   auto path = kj::str("/var/sandstorm/backups/", context.getParams().getBackupId());
572:   while (unlink(path.cStr()) < 0) {
573:     int error = errno;
574:     if (error == ENOENT) {
575:       break;
576:     } else if (error != EINTR) {
577:       KJ_FAIL_SYSCALL("unlink", error, path);
578:     }
579:   }
580:   return kj::READY_NOW;
